#!/usr/bin/env node

import { config } from '../src/config/index.js';
import { APIClient } from '../src/api/client.js';
import { logger } from '../src/utils/logger.js';

async function validateConfiguration() {
  console.log('🔍 Validating Get Notes MCP Configuration...\n');
  
  // Check API key
  if (!config.auth.token) {
    console.error('❌ GET_NOTE_API_KEY is not set');
    process.exit(1);
  }
  console.log('✅ API key is configured');
  
  // Check other config
  console.log(`✅ API Base URL: ${config.api.baseURL}`);
  console.log(`✅ Timeout: ${config.api.timeout}ms`);
  console.log(`✅ Retries: ${config.api.retries}`);
  console.log(`✅ Log Level: ${config.logging.level}`);
  
  // Test API connectivity
  console.log('\n🌐 Testing API connectivity...');
  
  try {
    const client = new APIClient();
    
    // Try a simple recall operation
    const result = await client.recallKnowledge('test', {
      topic_ids: ['test-topic'],
      top_k: 1
    });
    
    console.log('✅ API connectivity test passed');
    console.log('✅ Authentication successful');
    
  } catch (error) {
    if (error.message.includes('topic_id')) {
      console.log('✅ API connectivity test passed (expected topic validation error)');
      console.log('✅ Authentication successful');
    } else if (error.message.includes('401') || error.message.includes('Invalid API key')) {
      console.error('❌ API authentication failed - check your API key');
      process.exit(1);
    } else {
      console.warn('⚠️  API test failed:', error.message);
      console.log('✅ Configuration appears valid but API may be unavailable');
    }
  }
  
  console.log('\n🎉 Configuration validation complete!');
  console.log('\nTo start the server, run:');
  console.log('  npm start');
  console.log('\nOr use the start script:');
  console.log('  ./scripts/start.sh');
}

validateConfiguration().catch(error => {
  console.error('Validation error:', error);
  process.exit(1);
});